def parse_journal_ts(line):
    # Format: "Mar 15 HH:MM:SS"
    match = re.match(r'(\w{3}) (\d+) (\d+:\d+:\d+)', line)
    if match:
        month_str, day, time = match.groups()
        months = {'Jan':1,'Feb':2,'Mar':3,'Apr':4,'May':5,'Jun':6,'Jul':7,'Aug':8,'Sep':9,'Oct':10,'Nov':11,'Dec':12}
        month = months.get(month_str, 1)
        return f"2024-{month:02d}-{int(day):02d} {time}"
    return None

# Read and parse all log sources
